def count_numbers_with_positive_digit_sum(start, end):
    """
    Counts integers in the inclusive range [start, end] that have a positive digit sum.
    Handles negative numbers by summing the digits of their absolute value.
    Returns a dictionary with 'count' and 'numbers'.
    """
    def digit_sum(n):
        """Calculate the sum of digits of the absolute value of n."""
        return sum(int(d) for d in str(abs(n)))

    if start > end:
        raise ValueError("Start must be less than or equal to end.")

    result = []
    for num in range(start, end + 1):
        if digit_sum(num) > 0:
            result.append(num)

    return {
        "count": len(result),
        "numbers": result
    }

