def sort_letters_in_word(word):
    # Record positions of non-letters
    letters = [c for c in word if c.isalpha()]
    letters.sort(key=lambda c: c.lower())  # case-insensitive sort
    result = []
    it = iter(letters)
    for ch in word:
        if ch.isalpha():
            result.append(next(it))
        else:
            result.append(ch)
    return ''.join(result)

